To identify the participial phrase that functions as the subject complement in a sentence using C++ code, we need to follow these steps:

1. Tokenize the input text into words and tags.
2. Identify the main verb of the sentence.
3. Look for any participial phrases that modify the subject of the sentence.
4. Check if the participial phrase is functioning as the subject complement.
5. Extract the part of speech tag for the subject of the sentence.

Here's an example implementation using C++:

```c++
#include <iostream>
#include <vector>

using namespace std;

// Tag types
enum class PosTag { NOUN, VERB };

// Tag mapping function
auto tag_map = [](const string& word) {
    switch(word[0]) {
        case 'I': return PosTag::NOUN;
        default: return PosTag::VERB;
    }
};

// Parse tree node structure
struct Node {
    string token;
    vector<Node*> children;
    string pos_tag;
};

// Tree construction helper function
Node* parse_tree(const string& sentence) {
    vector<Node> nodes;
    size_t start = 0;
    while(start < sentence.size()) {
        // Find next non-space character
        auto end = find_if_not(begin(sentence), end(sentence), isspace);
        string word(end - begin(sentence), end);

        // Get part-of-speech tag
        auto pos_tag = tag_map(word);

        // Create new node with appropriate tag
        auto node = new Node();
        node->token = word;
        node->pos_tag = pos_tag == PosTag::NOUN ? "NN" : "VBG";
        node->children.clear();

        // Add child nodes (if any)
        if(pos_tag != PosTag::NOUN && pos_tag != PosTag::VERB)
            continue;

        ++start; // Skip spaces

        // If this is not a noun or verb, skip it
        if(pos_tag != PosTag::NOUN && pos_tag != PosTag::VERB)
            continue;

        // Find the first space after current position
        auto end_space = find_if_not(begin(sentence), end(sentence), isspace);
        if(end_space == end(sentence))
            break; // No more tokens found

        string rest(sentence.end(), end_space);
        auto subtree = parse_tree(rest);

        // Set parent node
        node->children.push_back(subtree);
    }

    return nodes[0];
}

