        // Original matrix
        int[][] myMatrix = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};

        // Extracted matrix containing the second and third rows, and the first column
        List<List<Integer>> extractedRows = new ArrayList<>();

